function HeroSection() {
  return (
    <section className="relative bg-[#f3f2ee]">
      {/* Two-column grid — height driven by content, not viewport */}
      <div className="mx-auto max-w-[1512px] px-8 md:px-16 lg:px-[115px] pt-[180px] md:pt-[220px] pb-12 md:pb-16 grid grid-cols-1 lg:grid-cols-[58fr_42fr]">

        {/* Left: headline */}
        <div>
          <h1
            className="text-[#0e3233] leading-[1.06] tracking-[-1.5px]"
            style={{ fontSize: "clamp(38px,5.2vw,76px)" }}
          >
            <LineReveal delay={0.04}>
              <span style={ttHovesMedium}>We're helping the world's</span>
            </LineReveal>
            <LineReveal delay={0.13}>
              <span style={ttHovesMedium}>best maritime teams</span>
            </LineReveal>
            <LineReveal delay={0.22}>
              <span style={ltCushion}>transform the way they work.</span>
            </LineReveal>
          </h1>
        </div>

        {/* Right: mission — top padding offsets it below the headline */}
        <div className="lg:pl-16 pt-12 lg:pt-[clamp(180px,18vw,280px)]">
          <motion.p
            className="mb-5 text-[#615D5D]"
            style={{ fontFamily: "monospace", fontSize: 10, letterSpacing: "0.15em", textTransform: "uppercase" }}
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.5, delay: 0.5, ease: EASE }}
          >
            Our Mission
          </motion.p>
          <motion.p
            className="text-[#262627] leading-[1.75]"
            style={{ ...ttHovesMedium, fontSize: 18 }}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.58, ease: EASE }}
          >
            We believe that when technology disappears into the work,
            people do their best work. For maritime teams — from deck
            officers to fleet managers — that means capturing the right
            information at the moment it matters, and translating it into
            decisions that keep ships safe, efficient, and always ahead.
          </motion.p>
          <motion.p
            className="mt-5 text-[#262627] leading-[1.75]"
            style={{ ...ttHovesMedium, fontSize: 18 }}
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.68, ease: EASE }}
          >
            Not by adding more tools. By removing the friction between
            what crews know and what the fleet can act on.
          </motion.p>
        </div>
      </div>

    </section>
  );
}

