function FounderNoteSection() {
  // Each sentence is its own animated unit, sequenced by delay
  const sentences: { text: string; mb: string }[] = [
    { text: "In 2019, we observed the maritime landscape changing rapidly — internet was becoming ubiquitous, storage was becoming cheaper, and sensing was gaining prominence.", mb: "mb-3" },
    { text: "We asked: what magical experiences can we create when maritime had these three forces come together?", mb: "mb-5" },
    { text: "That question earned us a seat at the EPS Techstars accelerator.", mb: "mb-3" },
    { text: "We jointly built applications with several thousand seafarers across several hundred ships.", mb: "mb-3" },
    { text: "What we have today is a frictionless platform that delivers operational intelligence the fastest way.", mb: "mb-5" },
    { text: "The best applications deliver immense joy when outcomes are achieved seamlessly — whether it's a taxi-riding service or wire transfers.", mb: "mb-3" },
    { text: "That is exactly what we're building for maritime.", mb: "" },
  ];

  const BASE = 0.18;  // delay for first sentence after card enters view
  const STEP = 0.14;  // stagger per sentence

  const signOffDelay    = BASE + sentences.length * STEP;        // ≈ 1.16s
  const signatureDelay  = signOffDelay + 0.2;                    // ≈ 1.36s
  const nameDelay       = signOffDelay + 0.25;                   // ≈ 1.41s

  return (
    <section className="relative bg-[#f3f2ee] pt-10 md:pt-14 pb-24 md:pb-32">
      <div className="mx-auto max-w-[1512px] px-8 md:px-16 lg:px-[115px]">

        {/* Small centered caption */}
        <motion.p
          className="text-center text-[#615D5D] max-w-[520px] mx-auto mb-10 leading-[1.75]"
          style={{ ...ttHoves, fontSize: 14 }}
          initial={{ opacity: 0, y: 10 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.5, ease: EASE }}
        >
          Great technology makes the complex disappear. At sea, that means the
          right information reaching the right person at exactly the right moment.
        </motion.p>

        {/* Large centered display heading */}
        <motion.h2
          className="text-center text-[#0e3233] leading-[1.1] mb-16 md:mb-20 mx-auto"
          style={{ ...ltCushion, fontSize: "clamp(30px,4.2vw,58px)", maxWidth: "860px" }}
          initial={{ opacity: 0, y: 16 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.6, delay: 0.08, ease: EASE }}
        >
          By capturing what crews know, and translating it into decisions, we make ships sail better.
        </motion.h2>

        {/* Letter card */}
        <motion.div
          className="relative max-w-[680px] mx-auto bg-white border border-[#E4E2DC] p-10 md:p-12"
          initial={{ opacity: 0, y: 24 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true, margin: "-80px" }}
          transition={{ duration: 0.55, ease: EASE }}
        >
          {/* Sentences — each animates in sequence */}
          <div className="pr-0 md:pr-32">
            {sentences.map((s, i) => (
              <motion.p
                key={i}
                className={`text-[#464646] leading-[1.85] ${s.mb}`}
                style={{ ...ttHoves, fontSize: 15 }}
                initial={{ opacity: 0, y: 8 }}
                whileInView={{ opacity: 1, y: 0 }}
                viewport={{ once: true, margin: "-20px" }}
                transition={{ duration: 0.5, delay: BASE + i * STEP, ease: EASE }}
              >
                {s.text}
              </motion.p>
            ))}
          </div>

          {/* Sign-off */}
          <div className="mt-10">
            <motion.p
              className="text-[#464646] mb-1"
              style={{ ...ttHoves, fontSize: 14 }}
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              viewport={{ once: true, margin: "-20px" }}
              transition={{ duration: 0.4, delay: signOffDelay, ease: EASE }}
            >
              Fair winds,
            </motion.p>

            {/* Signature — clip reveal starts after "Fair winds" */}
            <AnimatedSignature delay={signatureDelay} />

            <motion.div
              initial={{ opacity: 0 }}
              whileInView={{ opacity: 1 }}
              viewport={{ once: true, margin: "-20px" }}
              transition={{ duration: 0.4, delay: nameDelay, ease: EASE }}
            >
              <p className="mt-3 text-[#0e3233]" style={{ ...ttHovesMedium, fontSize: 14 }}>
                Surendra Lingareddy
              </p>
              <p className="text-[#615D5D]" style={{ ...ttHoves, fontSize: 12 }}>
                Founder &amp; CEO, Volteo Maritime
              </p>
            </motion.div>
          </div>

          {/* Stamp — Surendra's photo overlapping bottom-right corner */}
          <div
            className="absolute bottom-[-18px] right-8 md:right-12 w-[110px] md:w-[130px]"
            style={{ filter: "drop-shadow(0 4px 12px rgba(0,0,0,0.12))" }}
          >
            <div
              className="relative bg-white p-1.5"
              style={{ outline: "2px dashed #D9D9D9", outlineOffset: "-6px" }}
            >
              <img
                src={surendraImg}
                alt="Surendra Lingareddy"
                className="w-full aspect-square object-cover object-top"
                style={{ display: "block" }}
              />
            </div>
          </div>
        </motion.div>

      </div>
    </section>
  );
}

